-- ClassPages: UI kit. Clean look with restrained rounding (5 px panels, 3 px controls; icons and tiles square),
-- built from the addon's own art set (ClassPages/Media, generated by
-- tools/assets/make_assets.py): 9-slice panels with rounded corners and a thin ring, drop shadows, gradient sheens,
-- glow lines, switches with a knob, dropdown menus, rounded icons. Every texture is a white shape tinted with
-- SetVertexColor, so the palette lives here (STYLES) and no Blizzard template can change the look in a patch.
--
-- Public API (ns.UI)
--   SafeCreate(type, parent, templates, name) -> frame, template    first template that exists, else none
--   Skin(frame, style)     window, card, hl, popover, button, buttonOff, danger, ghost, tab, tabOn, slot, slotFocus,
--                          locked, row, rowOn   (a frame keeps the shape of its first style; later calls recolour)
--   Slice(frame, shape, corner, layer, sub, outset) -> slice (:SetColor, :SetShown)      Art(parent, name, layer, sub)
--   Text(parent, text, font?)                        Button(parent, text, width, onClick, style?) (:SetLabel, :SetIcon, .tip)
--   IconButton(parent, icon, size, onClick, style?)  Check(parent, label, checked, onChange)  (switch; :SetValue)
--   Dropdown(parent, width, options, value, onChange) (:SetValue, :SetOptions)   Cycle = Dropdown
--   Stepper(parent, label, min, max, step, onChange, fmt?, width?)   (:SetValue)
--   Card(parent, w, h, title?, note?) (:SetNote)     KV(parent, width) -> row (:Set(label, value, color?))
--   Icon(parent, size)  Bar(parent, w, h)  Edit(parent, w, onEnter)  Divider(parent)  ClassColor() -> r, g, b
--   Round(owner, tex, maskName?) -> mask | nil   round a texture's corners with a mask where supported
--   CloseMenu()                                  close the open dropdown menu
--   Edit: Enter or focus loss saves (onEnter(text)), Escape restores the old text; edit:SetValue(text) does not
--         overwrite while the player is typing
local ADDON, ns = ...
local L = ns.L

ns.UI = ns.UI or {}
local UI = ns.UI

UI.GOLD = { 1, 0.82, 0.45 }
UI.DIM = { 0.62, 0.57, 0.50 }
UI.TEXT = { 0.93, 0.90, 0.85 }
UI.MEDIA = "Interface\\AddOns\\" .. ADDON .. "\\Media\\"

function UI.SafeCreate(ftype, parent, templates, name)
  for _, t in ipairs(templates or {}) do
    local ok, f = pcall(CreateFrame, ftype, name, parent, t)
    if ok and f then return f, t end
  end
  return CreateFrame(ftype, name, parent), nil
end

function UI.ClassColor()
  local p = ns.Classes.Player()
  local c = p and p.color or { 0.8, 0.8, 0.8 }
  return c[1], c[2], c[3]
end

-- Art ------------------------------------------------------------------------------------------------
function UI.Art(parent, name, layer, sub)
  local t = parent:CreateTexture(nil, layer or "ARTWORK", nil, sub)
  t:SetTexture(UI.MEDIA .. name)
  return t
end

-- shape = { texture size, margin in texels }
local SHAPES = { rr5 = { 16, 7 }, rr3 = { 16, 6 }, pill = { 32, 15 }, tab = { 16, 7 }, shadow = { 64, 24 } }
for _, name in ipairs({ "rr5", "rr3", "pill", "tab" }) do SHAPES[name .. "_ring"] = SHAPES[name] end

-- Nine textures that stretch a rounded shape over a frame of any size. corner = corner size on screen (px),
-- outset = how far the slice reaches beyond the frame (shadows).
function UI.Slice(f, shape, corner, layer, sub, outset)
  local def = SHAPES[shape]
  local u = def[2] / def[1]
  local U = { 0, u, 1 - u, 1 }
  local c, o = corner, outset or 0
  local X = { { "LEFT", -o }, { "LEFT", c - o }, { "RIGHT", o - c }, { "RIGHT", o } }
  local Y = { { "TOP", o }, { "TOP", o - c }, { "BOTTOM", c - o }, { "BOTTOM", -o } }
  local s = { parts = {} }
  for row = 1, 3 do
    for col = 1, 3 do
      local t = f:CreateTexture(nil, layer, nil, sub)
      t:SetTexture(UI.MEDIA .. shape)
      t:SetTexCoord(U[col], U[col + 1], U[row], U[row + 1])
      t:SetPoint("TOPLEFT", f, Y[row][1] .. X[col][1], X[col][2], Y[row][2])
      t:SetPoint("BOTTOMRIGHT", f, Y[row + 1][1] .. X[col + 1][1], X[col + 1][2], Y[row + 1][2])
      s.parts[#s.parts + 1] = t
    end
  end
  function s:SetColor(r, g, b, a) for _, t in ipairs(self.parts) do t:SetVertexColor(r, g, b, a or 1) end end
  function s:SetShown(on) for _, t in ipairs(self.parts) do t:SetShown(on) end end
  return s
end

-- Styles ---------------------------------------------------------------------------------------------
local GOLD_EDGE = { 0.80, 0.62, 0.30, 1 }
local STYLES = {
  window    = { shape = "rr5", corner = 7, bg = { 0.063, 0.055, 0.047, 0.97 }, edge = { 0.52, 0.40, 0.21, 1 }, shadow = 0.65 },
  card      = { shape = "rr5", corner = 7, bg = { 0.100, 0.086, 0.068, 0.94 }, edge = { 0.29, 0.23, 0.16, 1 }, sheen = 0.035 },
  hl        = { shape = "rr5", corner = 7, bg = { 0.135, 0.100, 0.055, 0.96 }, edge = GOLD_EDGE, sheen = 0.06 },
  popover   = { shape = "rr5", corner = 7, bg = { 0.075, 0.064, 0.052, 0.98 }, edge = GOLD_EDGE, sheen = 0.04, shadow = 0.7 },
  button    = { shape = "rr3", corner = 6, bg = { 0.36, 0.25, 0.09, 1 }, edge = { 0.86, 0.67, 0.33, 1 }, sheen = 0.14, text = UI.GOLD },
  buttonOff = { shape = "rr3", corner = 6, bg = { 0.13, 0.12, 0.11, 1 }, edge = { 0.27, 0.25, 0.22, 1 }, sheen = 0.03, text = UI.DIM },
  danger    = { shape = "rr3", corner = 6, bg = { 0.30, 0.085, 0.06, 1 }, edge = { 0.78, 0.33, 0.24, 1 }, sheen = 0.10, text = { 1, 0.78, 0.72 } },
  ghost     = { shape = "rr3", corner = 6, bg = { 0.115, 0.098, 0.080, 0.95 }, edge = { 0.34, 0.27, 0.19, 1 }, sheen = 0.04, text = UI.TEXT },
  tab       = { shape = "tab", corner = 7, bg = { 0.090, 0.076, 0.060, 1 }, edge = { 0.27, 0.22, 0.15, 1 } },
  tabOn     = { shape = "tab", corner = 7, bg = { 0.205, 0.150, 0.068, 1 }, edge = GOLD_EDGE, sheen = 0.08, glow = 0.9 },
  slot      = { shape = "rr3", corner = 6, bg = { 0.032, 0.029, 0.026, 0.92 }, edge = { 0.29, 0.24, 0.17, 1 } },
  slotFocus = { shape = "rr3", corner = 6, bg = { 0.045, 0.040, 0.032, 0.95 }, edge = GOLD_EDGE },
  locked    = { shape = "rr3", corner = 6, bg = { 0.040, 0.040, 0.040, 0.92 }, edge = { 0.16, 0.16, 0.16, 1 } },
  row       = { shape = "rr3", corner = 6, bg = { 0.085, 0.072, 0.056, 0.75 }, edge = { 0.20, 0.16, 0.11, 0.9 } },
  rowOn     = { shape = "rr3", corner = 6, bg = { 0.175, 0.128, 0.060, 1 }, edge = GOLD_EDGE, sheen = 0.05 },
}
UI.STYLES = STYLES

-- Applies (or switches) a style. The shape is fixed by the first style; later calls only recolour, so a button can
-- turn into "buttonOff" and a talent slot can take the colours of any other style.
function UI.Skin(f, style)
  local s = STYLES[style] or STYLES.card
  local k = f.cpSkin
  if not k then
    k = { shape = s.shape, corner = s.corner }
    k.fill = UI.Slice(f, k.shape, k.corner, "BACKGROUND", -6)
    k.ring = UI.Slice(f, k.shape .. "_ring", k.corner, "BORDER", 1)
    f.cpSkin = k
  end
  k.fill:SetColor(s.bg[1], s.bg[2], s.bg[3], s.bg[4])
  k.ring:SetColor(s.edge[1], s.edge[2], s.edge[3], s.edge[4])
  if s.shadow and not k.shadow then k.shadow = UI.Slice(f, "shadow", 28, "BACKGROUND", -8, 14) end
  if k.shadow then k.shadow:SetColor(0, 0, 0, s.shadow or 0) end
  if s.sheen and not k.sheen then
    k.sheen = UI.Art(f, "fade_v", "BACKGROUND", -4)
    k.sheen:SetPoint("TOPLEFT", k.corner * 0.5, -1)
    k.sheen:SetPoint("TOPRIGHT", -k.corner * 0.5, -1)
    k.sheen:SetHeight(14)
  end
  if k.sheen then k.sheen:SetVertexColor(1, 0.86, 0.5, s.sheen or 0) end
  if s.glow and not k.glow then
    k.glow = UI.Art(f, "glow", "OVERLAY", 2)
    k.glow:SetBlendMode("ADD")
    k.glow:SetPoint("BOTTOMLEFT", 4, -5)
    k.glow:SetPoint("BOTTOMRIGHT", -4, -5)
    k.glow:SetHeight(12)
  end
  if k.glow then k.glow:SetVertexColor(1, 0.80, 0.38, s.glow or 0) end
  k.style = style
  return f
end

-- Basic widgets ----------------------------------------------------------------------------------------
function UI.Text(parent, text, font)
  local fs = parent:CreateFontString(nil, "OVERLAY", font or "GameFontHighlightSmall")
  fs:SetJustifyH("LEFT")
  fs:SetText(text or "")
  return fs
end

-- Thin line that fades out to both ends.
function UI.Divider(parent)
  local t = UI.Art(parent, "fade_h", "BORDER")
  t:SetHeight(1)
  t:SetVertexColor(0.55, 0.43, 0.24, 0.9)
  return t
end

local function tooltip(self)
  if self.tip and GameTooltip then
    GameTooltip:SetOwner(self, "ANCHOR_TOP")
    GameTooltip:AddLine(self.tip, 1, 1, 1, true)
    GameTooltip:Show()
  end
end

local function restyle(b)
  local s = STYLES[b.style] or STYLES.button
  UI.Skin(b, b.style)
  local c = s.text or UI.GOLD
  if b.hover then
    -- hover: a lighter plate and white text
    b.cpSkin.fill:SetColor(math.min(1, s.bg[1] * 1.3 + 0.03), math.min(1, s.bg[2] * 1.3 + 0.025), math.min(1, s.bg[3] * 1.3 + 0.02), s.bg[4])
    c = { 1, 1, 1 }
  end
  b.label:SetTextColor(c[1], c[2], c[3])
  if b.iconTex then b.iconTex:SetVertexColor(c[1], c[2], c[3]) end
end

-- Rounded plate button with hover and press feedback, optional tooltip (b.tip) and icon (b:SetIcon).
function UI.Button(parent, text, width, onClick, style)
  local b = CreateFrame("Button", nil, parent)
  b:SetSize(width or 100, 22)
  b.style = style or "button"
  b.label = b:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
  b.label:SetPoint("CENTER")
  b.label:SetText(text or "")
  restyle(b)
  b:SetScript("OnClick", function(self, button) if onClick then onClick(self, button) end end)
  b:SetScript("OnEnter", function(self) self.hover = true; restyle(self); tooltip(self) end)
  b:SetScript("OnLeave", function(self) self.hover = false; restyle(self); if GameTooltip then GameTooltip:Hide() end end)
  b:SetScript("OnMouseDown", function(self) self.label:SetPoint("CENTER", 0, -1) end)
  b:SetScript("OnMouseUp", function(self) self.label:SetPoint("CENTER", 0, 0) end)
  function b:SetLabel(t) self.label:SetText(t) end
  function b:SetStyle(st) self.style = st; restyle(self) end
  function b:SetIcon(name, size)
    if not self.iconTex then
      self.iconTex = UI.Art(self, name, "OVERLAY")
      self.iconTex:SetPoint("CENTER")
    end
    self.iconTex:SetTexture(UI.MEDIA .. name)
    self.iconTex:SetSize(size or 12, size or 12)
    restyle(self)
  end
  return b
end

function UI.IconButton(parent, icon, size, onClick, style)
  local b = UI.Button(parent, "", size, onClick, style or "ghost")
  b:SetHeight(size)
  b:SetIcon(icon, math.max(8, size - 10))
  return b
end

-- Switch: rounded track with a knob; the label sits to the right (b.text).
function UI.Check(parent, label, checked, onChange)
  local b = CreateFrame("Button", nil, parent)
  b:SetSize(30, 16)
  b.track = UI.Slice(b, "pill", 8, "BACKGROUND", -6)
  b.ringS = UI.Slice(b, "pill_ring", 8, "BORDER", 1)
  b.knob = UI.Art(b, "pill", "ARTWORK")
  b.knob:SetSize(12, 12)
  b.text = UI.Text(parent, label)
  b.text:SetPoint("LEFT", b, "RIGHT", 7, 0)
  function b:SetValue(v)
    self.value = v and true or false
    local r, g, bl = UI.ClassColor()
    self.knob:ClearAllPoints()
    if self.value then
      self.knob:SetPoint("RIGHT", -2, 0)
      self.track:SetColor(r * 0.55, g * 0.55, bl * 0.55, 1)
      self.ringS:SetColor(r, g, bl, 0.9)
      self.knob:SetVertexColor(1, 1, 1, 1)
    else
      self.knob:SetPoint("LEFT", 2, 0)
      self.track:SetColor(0.06, 0.055, 0.05, 1)
      self.ringS:SetColor(0.34, 0.28, 0.20, 1)
      self.knob:SetVertexColor(0.55, 0.52, 0.48, 1)
    end
  end
  b:SetValue(checked)
  b:SetScript("OnClick", function(self) self:SetValue(not self.value); if onChange then onChange(self.value) end end)
  return b
end

-- Dropdown menu -----------------------------------------------------------------------------------------
local menu, catcher
local MENU_ROW, MENU_MAX = 22, 12

local function closeMenu()
  if menu then menu:Hide() end
  if catcher then catcher:Hide() end
end

local function buildMenu()
  catcher = CreateFrame("Button", nil, UIParent)
  catcher:SetAllPoints(UIParent)
  catcher:SetFrameStrata("FULLSCREEN_DIALOG")
  catcher:SetScript("OnClick", closeMenu)
  catcher:Hide()
  menu = CreateFrame("Frame", "ClassPagesMenu", UIParent)
  menu:SetFrameStrata("TOOLTIP")
  menu:SetClampedToScreen(true)
  UI.Skin(menu, "popover")
  menu.rows = {}
  for i = 1, MENU_MAX do
    local row = CreateFrame("Button", nil, menu)
    row:SetHeight(MENU_ROW)
    row:SetPoint("TOPLEFT", 5, -5 - (i - 1) * MENU_ROW)
    row:SetPoint("TOPRIGHT", -5, -5 - (i - 1) * MENU_ROW)
    row.hl = UI.Slice(row, "rr3", 6, "BACKGROUND", -5)
    row.hl:SetColor(1, 0.8, 0.4, 0.14)
    row.hl:SetShown(false)
    row.text = UI.Text(row, "")
    row.text:SetPoint("LEFT", 8, 0)
    row.check = UI.Art(row, "check", "OVERLAY")
    row.check:SetSize(12, 12)
    row.check:SetPoint("RIGHT", -6, 0)
    row.check:SetVertexColor(UI.GOLD[1], UI.GOLD[2], UI.GOLD[3])
    row:SetScript("OnEnter", function(self) self.hl:SetShown(true) end)
    row:SetScript("OnLeave", function(self) self.hl:SetShown(false) end)
    row:SetScript("OnClick", function(self)
      closeMenu()
      if menu.onPick then menu.onPick(self.index) end
    end)
    menu.rows[i] = row
  end
  menu:Hide()
end

local function openMenu(owner, options, current, onPick)
  if not menu then buildMenu() end
  if menu:IsShown() and menu.owner == owner then closeMenu() return end
  menu.owner, menu.onPick = owner, onPick
  local n = math.min(#options, MENU_MAX)
  for i, row in ipairs(menu.rows) do
    local o = options[i]
    if o and i <= n then
      row.index = i
      row.text:SetText(L[o[2]])
      row.check:SetShown(i == current)
      row.hl:SetShown(false)
      row:Show()
    else
      row:Hide()
    end
  end
  menu:SetSize(math.max(owner:GetWidth() or 120, 120), n * MENU_ROW + 10)
  menu:ClearAllPoints()
  menu:SetPoint("TOPLEFT", owner, "BOTTOMLEFT", 0, -3)
  catcher:Show()
  menu:Show()
end
UI.CloseMenu = closeMenu

-- Button that opens a menu with options { {value, label} }; label = English key, translated on display.
function UI.Dropdown(parent, width, options, value, onChange)
  local b = UI.Button(parent, "", width, nil, "ghost")
  b.label:ClearAllPoints()
  b.label:SetPoint("LEFT", 9, 0)
  b.label:SetPoint("RIGHT", -22, 0)
  b.label:SetJustifyH("LEFT")
  b.label:SetWordWrap(false)
  b.chevron = UI.Art(b, "chevron", "OVERLAY")
  b.chevron:SetSize(12, 12)
  b.chevron:SetPoint("RIGHT", -7, 0)
  b.chevron:SetVertexColor(UI.GOLD[1], UI.GOLD[2], UI.GOLD[3])
  b:SetScript("OnMouseDown", nil)
  b:SetScript("OnMouseUp", nil)
  local idx = 1
  local function show() b:SetLabel(options[idx] and L[options[idx][2]] or "") end
  function b:SetValue(v)
    for i, o in ipairs(options) do if o[1] == v then idx = i end end
    show()
  end
  function b:SetOptions(list) options = list; idx = math.min(idx, #list); show() end
  function b:Pick(i)
    if not options[i] then return end
    idx = i
    show()
    if onChange then onChange(options[idx][1]) end
  end
  b:SetScript("OnClick", function(self) openMenu(self, options, idx, function(i) self:Pick(i) end) end)
  b:SetScript("OnHide", function(self) if menu and menu.owner == self then closeMenu() end end)
  b:SetValue(value)
  return b
end
UI.Cycle = UI.Dropdown

-- "Label        [-] 8 [+]": exact, works with the mouse only, never fights a drag.
function UI.Stepper(parent, label, min, max, step, onChange, fmt, width)
  local f = CreateFrame("Frame", nil, parent)
  f:SetSize(width or 220, 22)
  f.label = UI.Text(f, label)
  f.label:SetPoint("LEFT", 0, 0)
  local plus = UI.IconButton(f, "plus", 22)
  plus:SetPoint("RIGHT", 0, 0)
  f.value = f:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
  f.value:SetPoint("RIGHT", plus, "LEFT", -4, 0)
  f.value:SetWidth(40)
  f.value:SetJustifyH("CENTER")
  local minus = UI.IconButton(f, "minus", 22)
  minus:SetPoint("RIGHT", f.value, "LEFT", -4, 0)
  local current = min
  local function show() f.value:SetText((fmt or "%d"):format(current)) end
  function f:SetValue(v) current = math.max(min, math.min(max, tonumber(v) or min)); show() end
  local function change(dir)
    local mult = (IsShiftKeyDown and IsShiftKeyDown()) and 5 or 1
    local v = math.max(min, math.min(max, ns.Util.Round(current + dir * step * mult, 2)))
    if v == current then return end
    current = v
    show()
    if onChange then onChange(v) end
  end
  minus:SetScript("OnClick", function() change(-1) end)
  plus:SetScript("OnClick", function() change(1) end)
  minus.tip, plus.tip = L["Shift: steps of 5"], L["Shift: steps of 5"]
  f.minus, f.plus = minus, plus
  f:SetValue(min)
  return f
end

-- Card: panel with an optional title (aligned with the content) and a divider that fades out to both sides.
function UI.Card(parent, w, h, title, note)
  local c = CreateFrame("Frame", nil, parent)
  c:SetSize(w, h)
  UI.Skin(c, "card")
  if title then
    c.title = UI.Text(c, title, "GameFontNormal")
    c.title:SetPoint("TOPLEFT", 12, -10)
    c.title:SetTextColor(UI.GOLD[1], UI.GOLD[2], UI.GOLD[3])
    c.note = UI.Text(c, note or "")
    c.note:SetPoint("LEFT", c.title, "RIGHT", 8, 0)
    c.note:SetTextColor(UI.DIM[1], UI.DIM[2], UI.DIM[3])
    local line = UI.Divider(c)
    line:SetPoint("TOPLEFT", 8, -29)
    line:SetPoint("TOPRIGHT", -8, -29)
  end
  function c:SetNote(t) if self.note then self.note:SetText(t or "") end end
  return c
end

-- Key/value row: dim label left, value right-aligned.
function UI.KV(parent, width)
  local row = CreateFrame("Frame", nil, parent)
  row:SetSize(width, 18)
  row.k = UI.Text(row, "")
  row.k:SetPoint("LEFT", 0, 0)
  row.k:SetTextColor(UI.DIM[1], UI.DIM[2], UI.DIM[3])
  row.v = UI.Text(row, "", "GameFontHighlightSmall")
  row.v:SetPoint("RIGHT", 0, 0)
  row.v:SetJustifyH("RIGHT")
  function row:Set(label, value, color)
    self.k:SetText(label or "")
    self.v:SetText(value or "")
    self.v:SetTextColor(color and color[1] or UI.TEXT[1], color and color[2] or UI.TEXT[2], color and color[3] or UI.TEXT[3])
  end
  return row
end

-- Rounds a texture's corners with a mask where the client supports it.
function UI.Round(owner, tex, maskName)
  if not (owner.CreateMaskTexture and tex.AddMaskTexture) then return end
  local mask = owner:CreateMaskTexture()
  mask:SetTexture(UI.MEDIA .. (maskName or "mask_rr"), "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
  mask:SetAllPoints(tex)
  tex:AddMaskTexture(mask)
  return mask
end

-- Icon slot: square icon in a thin frame, rank badge in the corner (talents, spells).
function UI.Icon(parent, size)
  local f = CreateFrame("Button", nil, parent)
  f:SetSize(size, size)
  UI.Skin(f, "slot")
  f.tex = f:CreateTexture(nil, "ARTWORK")
  f.tex:SetPoint("TOPLEFT", 2, -2)
  f.tex:SetPoint("BOTTOMRIGHT", -2, 2)
  f.tex:SetTexCoord(0.07, 0.93, 0.07, 0.93)
  f.badge = f:CreateFontString(nil, "OVERLAY", "NumberFontNormalSmall")
  f.badge:SetPoint("BOTTOMRIGHT", -2, 2)
  return f
end

-- Progress bar: track and fill with small corners. Same calls as a StatusBar where the tabs use them.
function UI.Bar(parent, w, h)
  local bar = CreateFrame("Frame", nil, parent)
  bar:SetSize(w, h)
  local corner = math.min(6, h / 2)
  bar.cpSkin = { style = "bar" }
  bar.track = UI.Slice(bar, "rr3", corner, "BACKGROUND", -6)
  bar.track:SetColor(0.035, 0.032, 0.028, 0.95)
  bar.ringS = UI.Slice(bar, "rr3_ring", corner, "BORDER", 1)
  bar.ringS:SetColor(0.30, 0.25, 0.18, 1)
  bar.fillFrame = CreateFrame("Frame", nil, bar)
  bar.fillFrame:SetPoint("TOPLEFT", 1, -1)
  bar.fillFrame:SetPoint("BOTTOMLEFT", 1, 1)
  bar.fill = UI.Slice(bar.fillFrame, "rr3", math.max(1, corner - 1), "ARTWORK")
  bar.text = UI.Text(bar, "")
  bar.text:SetPoint("CENTER")
  function bar:SetStatusBarColor(r, g, b) self.fill:SetColor(r, g, b, 1) end
  function bar:SetValue(v)
    v = math.max(0, math.min(1, tonumber(v) or 0))
    local width = (w - 2) * v
    self.fillFrame:SetWidth(math.max(1, width))
    self.fill:SetShown(width >= math.max(2, corner))
  end
  bar:SetStatusBarColor(UI.ClassColor())
  bar:SetValue(0)
  return bar
end

function UI.Edit(parent, w, onEnter)
  local e = CreateFrame("EditBox", nil, parent)
  e:SetSize(w, 22)
  UI.Skin(e, "slot")
  e:SetFontObject("GameFontHighlightSmall")
  e:SetAutoFocus(false)
  e:SetTextInsets(8, 8, 0, 0)
  -- Enter or a click elsewhere saves, Escape restores the text from before the edit.
  e:SetScript("OnEscapePressed", function(self) self.cpCancel = true; self:ClearFocus() end)
  e:SetScript("OnEnterPressed", function(self) self:ClearFocus() end)
  e:SetScript("OnEditFocusGained", function(self)
    self.cpBefore, self.cpCancel, self.cpTyping = self:GetText(), false, true
    UI.Skin(self, "slotFocus")
  end)
  e:SetScript("OnEditFocusLost", function(self)
    UI.Skin(self, "slot")
    if not self.cpTyping then return end
    self.cpTyping = false
    if self.cpCancel then self:SetText(self.cpBefore or "") return end
    local text = self:GetText()
    if onEnter and text ~= self.cpBefore then onEnter(text) end
  end)
  -- For refreshes: background updates must not overwrite what the player is typing.
  function e:SetValue(text) if not self.cpTyping then self:SetText(text or "") end end
  return e
end
